SELECT COUNT(1) FROM app_wallet_ledger WHERE 1 = 1
AND ( CAST(user_id AS CHAR) LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(order_no, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(biz_ref, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(note, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(idempotency_key, '') LIKE CONCAT('%', #{keyword}, '%') )
AND biz_type = #{bizType}

SELECT id, user_id, biz_type, order_no, biz_ref, idempotency_key, delta_score, delta_gold_coin, note, created_at FROM app_wallet_ledger WHERE 1 = 1
AND ( CAST(user_id AS CHAR) LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(order_no, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(biz_ref, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(note, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(idempotency_key, '') LIKE CONCAT('%', #{keyword}, '%') )
AND biz_type = #{bizType}
ORDER BY id DESC LIMIT #{limit} OFFSET #{offset}
